INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `lang0`, `Probability0`, `em0_0`, `em0_1`) VALUES
(975017, 'We were the Empress\'s once. Then Vashj\'s. Now we are no one\'s but our own, and I mean to keep it that way.', 'We were the Empress\'s once. Then Vashj\'s. Now we are no one\'s but our own, and I mean to keep it that way.', 0, 1, 0, 1),
(975018, 'I watch the water. Whatever comes, it comes from the water.', 'I watch the water. Whatever comes, it comes from the water.', 0, 1, 0, 1),
(975019, 'Coral, kelp, and a dry corner if you can find one. Sit. Eat something. Then tell me who you are.', 'Coral, kelp, and a dry corner if you can find one. Sit. Eat something. Then tell me who you are.', 0, 1, 0, 1),
(990000, 'Come closer, little one. I can\'t see you, but I can hear the sea in you.', 'Come closer, little one. I can\'t see you, but I can hear the sea in you.', 0, 1, 0, 1),
(990001, 'The sea answers if you ask it quietly. The Empress never asked anything quietly.', 'The sea answers if you ask it quietly. The Empress never asked anything quietly.', 0, 1, 0, 1),
(990002, 'Kneel if you like. The sea doesn\'t care how you pray, only that you listen.', 'Kneel if you like. The sea doesn\'t care how you pray, only that you listen.', 0, 1, 0, 1),
(990003, 'Illidan taught us to drink from the Legion\'s cup and keep our own minds. Most of us did. Mostly.', 'Illidan taught us to drink from the Legion\'s cup and keep our own minds. Most of us did. Mostly.', 0, 1, 0, 1),
(990004, 'Mrgl... one, two, three, five. Mrgl counts. Mrgl always counts.', 'Mrgl... one, two, three, five. Mrgl counts. Mrgl always counts.', 0, 1, 0, 1),
(990005, 'Mrgl counts it. Mrgl counts it again. Nobody\'s things go missing. Nobody\'s.', 'Mrgl counts it. Mrgl counts it again. Nobody\'s things go missing. Nobody\'s.', 0, 1, 0, 1),
(990006, 'Stay close to me. Whatever you see, it already happened.', 'Stay close to me. Whatever you see, it already happened.', 0, 1, 0, 1),
(990007, 'Keep your trident up and your mouth shut. Scarscale is watching.', 'Keep your trident up and your mouth shut. Scarscale is watching.', 0, 1, 0, 1),
(990008, 'Hold the line. That is the whole of it. Hold the line.', 'Hold the line. That is the whole of it. Hold the line.', 0, 1, 0, 1),
(990009, 'Lady Serpentra says magic is only listening very hard. I listen very hard!', 'Lady Serpentra says magic is only listening very hard. I listen very hard!', 0, 1, 0, 1),
(990010, 'Ssaveth and I drilled on the same sand for a hundred years. He still drops his left.', 'Ssaveth and I drilled on the same sand for a hundred years. He still drops his left.', 0, 1, 0, 1),
(990011, 'Beasts don\'t lie. Neither does a bowstring. I trust both.', 'Beasts don\'t lie. Neither does a bowstring. I trust both.', 0, 1, 0, 1),
(990013, 'Quick fins, quiet tail. Whatever you\'re holding, hold it like it was always yours.', 'Quick fins, quiet tail. Whatever you\'re holding, hold it like it was always yours.', 0, 1, 0, 1),
(990014, 'The crèche taught me to pray to a statue. The sea taught me to pray to the sea.', 'The crèche taught me to pray to a statue. The sea taught me to pray to the sea.', 0, 1, 0, 1),
(990015, 'Earth under the water, fire under the earth, air over the waves. And the water, everywhere.', 'Earth under the water, fire under the earth, air over the waves. And the water, everywhere.', 0, 1, 0, 1),
(990016, 'My sister cooks with fire. I study it. The difference is mostly in the eyebrows.', 'My sister cooks with fire. I study it. The difference is mostly in the eyebrows.', 0, 1, 0, 1),
(990017, 'Fish don\'t care whose tide it is. Sit. Hold the line. Wait. That\'s all of it.', 'Fish don\'t care whose tide it is. Sit. Hold the line. Wait. That\'s all of it.', 0, 1, 0, 1),
(990018, 'Kelp, salt and a steady hand. Bind it before the sharks smell it.', 'Kelp, salt and a steady hand. Bind it before the sharks smell it.', 0, 1, 0, 1),
(990019, 'Everything that grows above the tide was once something that grew below it. Probably.', 'Everything that grows above the tide was once something that grew below it. Probably.', 0, 1, 0, 1),
(990020, 'Don\'t drink anything on that shelf. Don\'t smell that one. Don\'t look at that one too long.', 'Don\'t drink anything on that shelf. Don\'t smell that one. Don\'t look at that one too long.', 0, 1, 0, 1),
(990021, 'Shark, crab, boar. Everything wears a coat. Take it off gently.', 'Shark, crab, boar. Everything wears a coat. Take it off gently.', 0, 1, 0, 1),
(990022, 'Sharkskin turns a blade and keeps the salt out. What more do you want from a coat?', 'Sharkskin turns a blade and keeps the salt out. What more do you want from a coat?', 0, 1, 0, 1),
(990023, 'Under the sand, rock. Under the rock, ore. Under the ore, more rock. Dig.', 'Under the sand, rock. Under the rock, ore. Under the ore, more rock. Dig.', 0, 1, 0, 1),
(990024, 'Salt eats steel. So I make more steel. Bring me what\'s broken.', 'Salt eats steel. So I make more steel. Bring me what\'s broken.', 0, 1, 0, 1),
(990025, 'A net is a robe with holes in it. Close the holes. Now it\'s a robe.', 'A net is a robe with holes in it. Close the holes. Now it\'s a robe.', 0, 1, 0, 1),
(990026, 'The goblins throw away the best things. Gears! Springs! Things that go bang!', 'The goblins throw away the best things. Gears! Springs! Things that go bang!', 0, 1, 0, 1),
(990027, 'Sing to a pearl long enough and it remembers the song. So does a blade.', 'Sing to a pearl long enough and it remembers the song. So does a blade.', 0, 1, 0, 1),
(990028, 'Coral, pearl, a little stone from the land-walkers. Cut it true.', 'Coral, pearl, a little stone from the land-walkers. Cut it true.', 0, 1, 0, 1),
(990029, 'Squid ink on shell. Write it down, little one. Somebody will try to make you forget.', 'Squid ink on shell. Write it down, little one. Somebody will try to make you forget.', 0, 1, 0, 1),
(990030, 'Thread, salt, vials, candles, dust. Vyssa keeps the food; I keep everything else.', 'Thread, salt, vials, candles, dust. Vyssa keeps the food; I keep everything else.', 0, 1, 0, 1),
(990031, 'Arrows, shot, and the things a rogue dips her blades in. Don\'t lick your fingers.', 'Arrows, shot, and the things a rogue dips her blades in. Don\'t lick your fingers.', 0, 1, 0, 1),
(990032, 'What goes into the clam stays in the clam. I have the only key. I sleep on it.', 'What goes into the clam stays in the clam. I have the only key. I sleep on it.', 0, 1, 0, 1),
(990033, 'The currents run under every shore of Azshara. Tell me where, and hold your breath.', 'The currents run under every shore of Azshara. Tell me where, and hold your breath.', 0, 1, 0, 1),
(990035, 'Every tail in this crèche is written in my ledger. Hatched, counted, fed, taught. Yours too.', 'Every tail in this crèche is written in my ledger. Hatched, counted, fed, taught. Yours too.', 0, 1, 0, 1),
(990036, 'Tail low! Trident high! Chin... wherever your chin goes. FORM!', 'Tail low! Trident high! Chin... wherever your chin goes. FORM!', 0, 1, 0, 1),
(990037, 'What are you looking at? Look at the Empress. That\'s what she\'s for.', 'What are you looking at? Look at the Empress. That\'s what she\'s for.', 0, 1, 0, 1),
(990038, 'Guards first. Matron second. Hatchlings third. You? You\'re a tide-runner. You eat what\'s left.', 'Guards first. Matron second. Hatchlings third. You? You\'re a tide-runner. You eat what\'s left.', 0, 1, 0, 1),
(990039, 'The vault is the Empress\'s. What sings in it is the Empress\'s. Move along, runner.', 'The vault is the Empress\'s. What sings in it is the Empress\'s. Move along, runner.', 0, 1, 0, 1),
(990052, 'Hsss... zzz... the Empress... zzz... my shift...', 'Hsss... zzz... the Empress... zzz... my shift...', 0, 1, 0, 1),
(990053, 'Bow steady. Breath slow. The beast knows when your heart lies to it.', 'Bow steady. Breath slow. The beast knows when your heart lies to it.', 0, 1, 0, 1),
(990054, '...', '...', 0, 1, 0, 1),
(990055, 'Frost first. Frost is obedient. Fire is for when you have earned the Matron\'s trust.', 'Frost first. Frost is obedient. Fire is for when you have earned the Matron\'s trust.', 0, 1, 0, 1),
(990056, 'Earth, fire, water, air. The Empress commands them all. We only borrow them.', 'Earth, fire, water, air. The Empress commands them all. We only borrow them.', 0, 1, 0, 1),
(990057, 'The fish don\'t recite the creed. I like the fish.', 'The fish don\'t recite the creed. I like the fish.', 0, 1, 0, 1),
(990058, 'Kelp and salt. Bind it tight. The hatchlings bite.', 'Kelp and salt. Bind it tight. The hatchlings bite.', 0, 1, 0, 1),
(990059, 'Arrows, shot, candles, thread. Signed for. Everything here is signed for.', 'Arrows, shot, candles, thread. Signed for. Everything here is signed for.', 0, 1, 0, 1),
(990060, '...mrgl. Glubb old. Glubb tired. Glubb hungry.', '...mrgl. Glubb old. Glubb tired. Glubb hungry.', 0, 1, 0, 1),
(990068, 'The hatchling looks at your fingers. It has opinions about fingers.', 'The hatchling looks at your fingers. It has opinions about fingers.', 0, 1, 0, 1),
(990069, 'Mod Me Novas Dana! Mandos! E Far Ash! E Lon Ador, E Lon O Borne Goth, E Lon O Daegil Ve Borne Ras!', 'Mod Me Novas Dana! Mandos! E Far Ash! E Lon Ador, E Lon O Borne Goth, E Lon O Daegil Ve Borne Ras!', 0, 1, 0, 1),
(990079, 'You\'re the new page? Good. Carry, bow, say nothing. That\'s the whole of court.', 'You\'re the new page? Good. Carry, bow, say nothing. That\'s the whole of court.', 0, 1, 0, 1),
(990081, 'Well-water again? It tastes of the sea. Everything in this city has started to taste of the sea.', 'Well-water again? It tastes of the sea. Everything in this city has started to taste of the sea.', 0, 1, 0, 1),
(990082, 'Light of Lights. Blessed be her name. Blessed be her statue. Was that a bow? Bow properly, page.', 'Light of Lights. Blessed be her name. Blessed be her statue. Was that a bow? Bow properly, page.', 0, 1, 0, 1),
(990083, 'A new page? How charming. Come closer, page. Nobody here bites. Well. Almost nobody.', 'A new page? How charming. Come closer, page. Nobody here bites. Well. Almost nobody.', 0, 1, 0, 1);
