INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(990090, 0, 0, 'I\'ve been alone for ten thousand years.', 14, 0, 100, 0, 0, 995048, 0, 0, 'mod-murloc-naga'),
(990090, 1, 0, 'Betrayer...', 14, 0, 100, 0, 0, 0, 0, 0, 'mod-murloc-naga'),
(990090, 2, 0, 'In truth, it was I who was betrayed...', 14, 0, 100, 0, 0, 0, 0, 0, 'mod-murloc-naga'),
(990090, 3, 0, 'Still I am hunted...', 14, 0, 100, 0, 0, 0, 0, 0, 'mod-murloc-naga'),
(990090, 4, 0, 'Still I am hated...', 14, 0, 100, 0, 0, 0, 0, 0, 'mod-murloc-naga'),
(990090, 5, 0, 'Now, my blind eyes see what others cannot!', 14, 0, 100, 0, 0, 0, 0, 0, 'mod-murloc-naga'),
(990090, 6, 0, 'That sometimes the hand of fate must be forced!', 14, 0, 100, 0, 0, 0, 0, 0, 'mod-murloc-naga'),
(990091, 0, 0, 'I stand ready.', 12, 0, 100, 0, 0, 995000, 0, 0, 'mod-murloc-naga'),
(990000, 0, 0, 'My song echoes from the deeps.', 12, 0, 100, 0, 0, 995021, 0, 0, 'mod-murloc-naga'),
(990000, 1, 0, 'The tide turns.', 12, 0, 100, 0, 0, 995026, 0, 0, 'mod-murloc-naga'),
(990035, 0, 0, 'We were drowned, and the Empress lifted us.', 12, 0, 100, 1, 0, 0, 0, 0, 'mod-murloc-naga'),
(990035, 1, 0, 'We were lost in the dark, and the Empress found us. Her tide is our tide!', 12, 0, 100, 53, 0, 0, 0, 0, 'mod-murloc-naga'),
(990036, 0, 0, 'I think I have swimmer\'s ear.', 15, 0, 100, 0, 0, 995045, 0, 0, 'mod-murloc-naga'),
(990000, 2, 0, 'Don\'t be afraid.', 12, 0, 100, 1, 0, 995022, 0, 0, 'mod-murloc-naga'),
(990035, 2, 0, 'Lines! The Empress\'s envoy comes! Every tail to its mark!', 12, 0, 100, 53, 0, 0, 0, 0, 'mod-murloc-naga'),
(990071, 0, 0, 'I come to you now, at the turn of the tide.', 12, 0, 100, 0, 0, 995040, 0, 0, 'mod-murloc-naga'),
(990000, 3, 0, 'The Awakening.', 12, 0, 100, 1, 0, 0, 0, 0, 'mod-murloc-naga'),
(990090, 7, 0, 'Now go forth...', 14, 0, 100, 0, 0, 0, 0, 0, 'mod-murloc-naga'),
(990090, 8, 0, 'Unleash the tides of doom...', 14, 0, 100, 0, 0, 0, 0, 0, 'mod-murloc-naga'),
(990090, 9, 0, 'Upon all who would oppose us!', 14, 0, 100, 53, 0, 0, 0, 0, 'mod-murloc-naga'),
(990091, 1, 0, 'Illidan will show us the path to power!', 12, 0, 100, 53, 0, 995017, 0, 0, 'mod-murloc-naga'),
(990035, 3, 0, 'To the brazier. All of you. The envoy will speak.', 12, 0, 100, 53, 0, 0, 0, 0, 'mod-murloc-naga'),
(990073, 0, 0, 'Ash\'valana thure.', 12, 0, 100, 0, 0, 995025, 0, 0, 'mod-murloc-naga'),
(990073, 1, 0, 'For Nazjatar!', 12, 0, 100, 0, 0, 995032, 0, 0, 'mod-murloc-naga'),
(990073, 2, 0, 'Our alliance binds me.', 12, 0, 100, 0, 0, 995041, 0, 0, 'mod-murloc-naga'),
(990073, 3, 0, 'By land or sea.', 12, 0, 100, 0, 0, 995024, 0, 0, 'mod-murloc-naga'),
(990073, 4, 0, 'I will honor our pact.', 12, 0, 100, 0, 0, 995031, 0, 0, 'mod-murloc-naga'),
(990073, 5, 0, 'The tide turns.', 12, 0, 100, 0, 0, 995026, 0, 0, 'mod-murloc-naga'),
(990070, 0, 0, 'These are the songs of the drowned and the disobedient. The Empress remembers for us. Be grateful.', 12, 0, 100, 1, 0, 0, 0, 0, 'mod-murloc-naga'),
(990036, 1, 0, 'The day of our invasion shall be known as B-Day.', 12, 0, 100, 0, 0, 995046, 0, 0, 'mod-murloc-naga'),
(990036, 2, 0, 'The day of our invasion shall be known as B-Day.', 12, 0, 100, 0, 0, 995046, 0, 0, 'mod-murloc-naga'),
(990037, 0, 0, 'It isn\'t mine! It\'s the new one\'s! Ask the new one! ASK THEM!', 14, 0, 100, 53, 0, 0, 0, 0, 'mod-murloc-naga'),
(990037, 1, 0, 'Matron! Matron, please! It was them!', 14, 0, 100, 15, 0, 0, 0, 0, 'mod-murloc-naga'),
(990035, 4, 0, 'Take him to the deep cells. I will write it down.', 12, 0, 100, 1, 0, 0, 0, 0, 'mod-murloc-naga'),
(990069, 0, 0, 'Waldir Koshvel Me Wos? O Odes Nuff Lithtos! Dana, Odes An, Odes An, Noth Borne, Noth Ash Landowar Eynes E Ash!', 12, 0, 100, 1, 0, 0, 0, 0, 'mod-murloc-naga'),
(990069, 1, 0, 'Algos! Algos! Hamerung! Lars Mandos O Algos!', 14, 0, 100, 25, 0, 0, 0, 0, 'mod-murloc-naga'),
(990074, 0, 0, 'Tide-Broken! The shrine! Leave the hatchlings be!', 14, 0, 100, 53, 0, 0, 0, 0, 'mod-murloc-naga'),
(990000, 4, 0, 'They\'ve come. Open the cage, little one. Now.', 12, 0, 100, 1, 0, 0, 0, 0, 'mod-murloc-naga');
