INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `RewardText`, `Emote2`) VALUES
(992000, 1, 'Good. The light knows you now. I have written your name under the others. Do not make me cross it out.', 0),
(992001, 15, 'Hmph. You hit like a tide-runner. That\'s an improvement on how you looked this morning. Take a weapon. Take it before I change my mind.', 1),
(992002, 1, 'Eight. The hatchlings will sleep. You will not; there is always more work. But you may sit for a moment.', 0),
(992003, 1, 'Six beds. Six to a bed. Thirty-six. That is the number. That is what I write.', 0),
(992004, 53, 'I won. Don\'t argue, I was on the beach first, everyone saw. And now Kraveth says we BOTH scrub the drill ground, because we were \'out of the line\'. This is your fault.', 0),
(992005, 1, 'Hm. Shining. Good. ...What? Why are you looking at the pool? Nothing sings in the pool. Back to the line.', 0),
(992006, 467, 'Eight. The guards first, then the Matron, then the hatchlings. The heads go to the mur\'gul. You get the smell on your hands. That\'s tide-runner\'s wages.', 0),
(992007, 4, 'Glubb eats! Glubb pats your tail! Kraveth counts the basket... Mrgl counts it for him. One, two, three, five. Kraveth says good. Mrgl says nothing.', 2),
(992008, 53, 'The counting one. Of course. They always think the count is theirs. Not any more. The Matron will hear you were loyal.', 0),
(992009, 1, 'You have a kind way of setting down a basket. Most of them throw it. Sit a moment, tide-runner. Nobody comes to the Deep Pool for the view.', 0),
(992010, 11, 'There you are! The new page. Stop gaping at the lanterns, everyone gapes at the lanterns. Come, there\'s work.', 3),
(992011, 11, 'Spat out, bowed at, and Ilthanos sulking by the lanterns. Vashj gave him the look. You saw the look? Nobody survives the look. Now listen... the queen is coming out.', 4),
(992012, 1, '...You\'re awake. Good. Breathe. Your Matron says the Empress saved us that night. Tell me, little one. Did you see anyone saving anyone?', 0),
(992013, 1, 'She stopped at you. She looked a long time. I have written that down too. I would like to know why.', 0),
(992014, 66, 'One, two, three, four, five, six. Six stones for the brazier. Go and sleep, runner. Dawn comes early on the shrine.', 0),
(992015, 1, 'This one I know. It was mine, before they unsung it out of me. Listen... it still knows its own name. The Awakening.', 0),
(992016, 15, 'You came up with us. Look at them all, on the sand, blinking like hatchlings. Look up. He\'s still there.', 25),
(992017, 1, 'You\'re back. Your Matron says we rose for the Empress. You were there. You heard who called us up. So you tell me, little one. Who called?', 0),
(992018, 15, 'You didn\'t move. Well... your tail moved. Tails always move. That stance is yours now: the wall\'s stance. Keep the shield, too. I have plenty. Hatchlings keep dropping them on me.', 0),
(992019, 21, 'It followed you. Now: the beast you choose will choose you back, any beast, anywhere the sea reaches. Call it, send it away, feed it, wake it when it falls. That\'s the whole of it. The rest is love.', 25),
(992020, 273, '...Good. Now you know the weight of a thing that isn\'t yours. Remember it.', 0),
(992021, 463, 'They\'re up and fighting over the shell again. That\'s how you know a prayer worked. Keep this pearl; it was mine when I was a runner.', 0),
(992022, 463, 'Hold them. Feel the earth under the stone, and the fire inside the ember? Now they\'re yours, carved into totems. Plant them, and they\'ll answer.', 0),
(992023, 21, 'Three, and nothing on fire. Here. A shell that\'s been in the cold too long. It\'ll help you think.', 0),
(992024, 51, 'There. It knows you now. Call it, and it comes, and it stands between you and whatever\'s coming. Don\'t tell the Matron where you learned that. Don\'t tell her where I learned it.', 0),
(992025, 1, 'You heard her. Be grateful. ...Why are you shaking? It is only noise. Go back to your work.', 0),
(992026, 1, 'He saw, and he didn\'t speak? Then he\'s lonelier than you know. That one roars loudest because nobody ever answered him. Be careful with him, little one. And be kind, if you can.', 0),
(992027, 1, 'Done? Then he\'s the heretic, if anyone is. I don\'t like it either. I\'ve done worse to better people, a long time ago, for a queen. That\'s the trouble with surviving: you get the practice.', 0),
(992028, 4, 'The egg. The Matron\'s missing egg. Mur\'gul keep it warm, here, by the Pool, so it hears her sing. One. Mrgl counts it. One. Mrgl counts it again. Still one.', 25),
(992029, 25, 'You saw the egg. The Matron\'s missing egg. Mur\'gul keep it warm by the Pool so it hears her sing. Mrgl counts it. One. Mrgl counts it again. One. Mrgl still helps. Mrgl is that kind of mur\'gul.', 18),
(992030, 11, 'Keys! Big key! Shh. Shh. Hide it. And the loud one... the loud one saw, and he looked away. Mrgl saw him look away.', 4),
(992031, 11, 'Keys! Big key! Hide it. ...The loud one is gone to the Matron. Screaming. He screamed your name, you know. Nobody listened. Nobody ever listens to tide-runners.', 24),
(992032, 4, 'Gone? Running? Good! Running is good. Mrgl likes running. Mrgl hopes it runs all the way home.', 0),
(992033, 274, 'Coins! Mrgl counts. One, two, three, five... the green one is screaming. Mrgl hears it from here. Mrgl doesn\'t like the screaming.', 0),
(992034, 1, 'So this is the one who carried the keeper out. Mur\'gul, a warlock, an egg, and a tide-runner with the Empress\'s sigil still on the shoulder. Welcome to the Hollow. Sit before you fall down. You\'re one of us now, whether you meant to be or not.', 15);
INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`) VALUES
(992000, 1, 6, 'The Empress is waiting. So am I.'),
(992001, 1, 6, 'Six! I said six! Can you count, or do I send you to the mur\'gul for lessons?'),
(992002, 1, 6, 'I have not heard eight clawlings die. I listen for these things.'),
(992003, 1, 6, 'The ledger is open. The column is empty.'),
(992004, 1, 6, 'Slow. Slooow. Are you swimming or sinking?'),
(992005, 1, 6, 'I still can\'t see my face in her. That\'s barnacles, not my face.'),
(992006, 1, 6, 'Still empty. It echoes. A pot shouldn\'t echo.'),
(992007, 1, 6, 'Glubb still hungry? Mrgl hears his belly.'),
(992008, 1, 6, 'Well? Who?'),
(992009, 1, 6, 'She won\'t eat if you hold it. Put it inside.'),
(992010, 1, 6, 'The fountain. Find her by the fountain.'),
(992011, 1, 6, 'One bowl, one lord. You can\'t carry the fountain.'),
(992012, 1, 6, 'Stay with us. Stay.'),
(992013, 1, 6, 'Your mark. Now.'),
(992014, 1, 6, 'Six. I count to six. I count very carefully.'),
(992015, 1, 6, 'I can hear it from here. Give it to me.'),
(992016, 1, 6, 'Up. Come up. Everyone is going up.'),
(992017, 1, 6, 'Answer her!'),
(992018, 1, 6, 'Shield. Up.'),
(992019, 1, 6, 'It bit you? Good. Now it knows your taste.'),
(992020, 1, 6, '...'),
(992021, 1, 6, 'Pray. Quietly. The wardens don\'t need to hear.'),
(992022, 1, 6, 'An ember. A stone. Before the wardens notice the brazier smoking.'),
(992023, 1, 6, 'Is that smoke? I said frost.'),
(992024, 1, 6, 'Still loose? Then it still thinks it\'s its own.'),
(992025, 1, 6, 'To the brazier.'),
(992027, 1, 6, 'His bedding. By the old pagoda. Quietly.'),
(992028, 1, 6, 'Here! Here. Look in the kelp.'),
(992029, 1, 6, 'Kelp. Look in the kelp.'),
(992030, 1, 6, 'Jingle? No jingle? Shh.'),
(992031, 1, 6, 'Jingle? No jingle? Shh.'),
(992032, 1, 6, 'Still in the net? Still loud?'),
(992033, 1, 6, 'Purse? Coins? Shh.'),
(992034, 1, 6, 'The key, little one. The key.');
